/* ───────────────────────────────────────────────────────────────────────────
   VIRTUAL SCROLL / INFINITE SCROLL
   ─────────────────────────────────────────────────────────────────────────── */

.virtual-scroll {
  overflow-y: auto;
  /* Hint the browser to keep offscreen children cheap. */
  contain: strict;
  will-change: transform;
}
.virtual-scroll-sizer { position: relative; width: 100%; }
.virtual-scroll-viewport { position: absolute; top: 0; left: 0; right: 0; }
.virtual-scroll-item { contain: layout style; }
/* Sentinel the IntersectionObserver watches to request the next page. */
.infinite-sentinel { height: 1px; margin-top: -1px; }
.infinite-loader { display: flex; align-items: center; justify-content: center; gap: 8px; padding: 20px; color: var(--santy-text-muted, #6b7280); font-size: 13px; }

/* ───────────────────────────────────────────────────────────────────────────
