}
.loading-overlay-fixed { position: fixed; z-index: 900; }
.loading-overlay-text { font-size: 13px; color: var(--santy-text-muted, #6b7280); }
.backdrop {
  position: fixed;
  inset: 0;
  z-index: 190;
  background: rgba(0,0,0,.5);
}
.backdrop-blur { backdrop-filter: blur(4px); }
.backdrop-light { background: rgba(255,255,255,.7); }

/* ───────────────────────────────────────────────────────────────────────────
